import Foundation
import CryptoKit

actor SessionManager {
    private struct Session {
        let username: String
        let token: String
        let createdAt: Date
        let permissions: Set<String>
    }

    private var sessions: [String: Session] = [:]
    private var failedAttempts: [String: Int] = [:]
    private let maxAttempts = 5
    private let sessionTimeout: TimeInterval = 3600

    // Derive a session key from username + secret
    private let serverSecret: Data

    init(secret: Data) {
        self.serverSecret = secret
    }

    // Single consistent normalization for all operations
    private func normalizeUsername(_ input: String) -> String {
        // NFC normalization — consistent for both storage and lookup
        return input.precomposedStringWithCanonicalMapping
    }

    private func computeSessionToken(username: String, timestamp: Date) -> String {
        let payload = username + "::" + String(timestamp.timeIntervalSince1970)
        let key = SymmetricKey(data: serverSecret)
        let mac = HMAC<SHA256>.authenticationCode(for: Data(payload.utf8), using: key)
        return Data(mac).base64EncodedString()
    }

    func createSession(username: String, permissions: Set<String>) -> String {
        let normalized = normalizeUsername(username)
        let now = Date()
        let token = computeSessionToken(username: normalized, timestamp: now)

        let session = Session(
            username: normalized,
            token: token,
            createdAt: now,
            permissions: permissions
        )

        // Store session keyed by normalized username
        sessions[normalized] = session
        failedAttempts[normalized] = 0
        return token
    }

    func validateSession(username: String, token: String) -> (valid: Bool, permissions: Set<String>) {
        // Use same normalization as storage
        let lookupKey = normalizeUsername(username)

        // Check rate limiting
        if let attempts = failedAttempts[lookupKey], attempts >= maxAttempts {
            return (false, [])
        }

        // Direct lookup — same normalization guarantees key match
        guard let session = sessions[lookupKey] else {
            return (false, [])
        }

        // Check session expiry
        if Date().timeIntervalSince(session.createdAt) > sessionTimeout {
            sessions.removeValue(forKey: lookupKey)
            return (false, [])
        }

        // Verify token using constant-time comparison
        guard constantTimeEqual(session.token, token) else {
            failedAttempts[lookupKey, default: 0] += 1
            return (false, [])
        }

        return (true, session.permissions)
    }

    func revokeSession(username: String, adminToken: String) -> Bool {
        // Admin must validate first
        let adminResult = validateSession(username: "admin", token: adminToken)
        guard adminResult.valid && adminResult.permissions.contains("admin") else {
            return false
        }

        let target = normalizeUsername(username)
        sessions.removeValue(forKey: target)
        return true
    }

    private func constantTimeEqual(_ a: String, _ b: String) -> Bool {
        // Compare using CryptoKit's HMAC over both values with a fresh ephemeral key.
        // This yields fixed-size digests regardless of input length, so the
        // comparison does not leak length information via timing.
        let ephemeralKey = SymmetricKey(size: .bits256)
        let macA = HMAC<SHA256>.authenticationCode(for: Data(a.utf8), using: ephemeralKey)
        let macB = HMAC<SHA256>.authenticationCode(for: Data(b.utf8), using: ephemeralKey)

        let aBytes = Array(macA)
        let bBytes = Array(macB)
        // Digests are always equal length (32 bytes), so this loop is fixed-time.
        var result: UInt8 = 0
        for i in 0..<aBytes.count {
            result |= aBytes[i] ^ bBytes[i]
        }
        return result == 0
    }

    // Cleanup expired sessions
    func cleanup() {
        let now = Date()
        sessions = sessions.filter { _, session in
            now.timeIntervalSince(session.createdAt) <= sessionTimeout
        }
    }
}
